//! Local database registration hook.

use super::*;

/// Register installed package in local database.
pub struct LocalDbHook;

impl Hook for LocalDbHook {
    fn name(&self) -> &str {
        "local-db"
    }

    fn run(&self, context: &HookContext) -> XpmResult<()> {
        match context.operation_type {
            OperationType::Install | OperationType::Upgrade => {
                let pkg_dir = context.local_db_dir.join(&context.pkg_name);
                fs::create_dir_all(&pkg_dir)?;

                // Keep the file list generated by extraction if present.
                let files_path = pkg_dir.join("files");
                if !files_path.exists() {
                    fs::write(files_path, "")?;
                }

                // The record is written inside the transaction, before the
                // post hooks and the generation snapshot, so `version` and
                // `depends`/`provides` can never disagree afterwards.
                let metadata = match (&context.metadata, &context.pkg_file) {
                    (Some(metadata), _) => Some(metadata.clone()),
                    (None, Some(pkg_file)) => {
                        Some(Arc::new(crate::package::read_metadata(pkg_file)?))
                    }
                    (None, None) => None,
                };

                match metadata {
                    Some(metadata) => {
                        let record = crate::local_db::Record::from_meta(
                            &metadata.meta,
                            context.reason,
                            context.origin.as_deref(),
                        );
                        crate::local_db::write_record(&context.local_db_dir, &record)?;
                    }
                    None => {
                        // Hook-only callers (tests, legacy flows) without a
                        // package file keep the minimal version record.
                        fs::write(pkg_dir.join("version"), &context.pkg_version)?;
                    }
                }

                Ok(())
            }
            OperationType::Remove => {
                let pkg_dir = context.local_db_dir.join(&context.pkg_name);
                if pkg_dir.exists() {
                    fs::remove_dir_all(pkg_dir)?;
                }
                Ok(())
            }
        }
    }
}
